{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01DrnzWMF4ohdJKbfSyBAaez","type":"tool_result","content":"1	/** Shared intake + REVIEW-gate verifier for managed reviewer evidence. */
2	
3	import { createHash } from 'node:crypto';
4	import { existsSync, readFileSync, readdirSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	import {
8	  managedHostRunDirectory,
9	  managedHostRunReceipt,
10	  readManagedHostRunBinding,
11	  readManagedReviewEvidenceProposal,
12	  type ManagedHostRunReceipt,
13	  type ManagedReviewEvidenceProposal,
14	} from './managed-host-run.js';
15	import { isStrictManagedReviewFindingProposal } from './host-run.js';
16	import { loadConfig } from './config.js';
17	import { resolvePromptRoleBody } from './prompt-role-contract-registry.js';
18	import {
19	  buildProofAdmissibilityDiagnostic,
20	  type ProofAdmissibilityDiagnostic,
21	} from './proof-admissibility-gates.js';
22	import type { Finding, ManagedReviewEvidenceBinding, ReviewPass, ReviewRun } from './types.js';
23	import { digestCanonicalJson } from './digest.js';
24	
25	export interface ManagedReviewEvidenceVerification {
26	  valid: boolean;
27	  reason: string;
28	  diagnostic: ProofAdmissibilityDiagnostic;
29	  receipt: ManagedHostRunReceipt | null;
30	  proposal: ManagedReviewEvidenceProposal | null;
31	}
32	
33	function sha256(text: string): string {
34	  return `sha256:${createHash('sha256').update(text, 'utf8').digest('hex')}`;
35	}
36	
37	function rawSha256(text: string): string {
38	  return createHash('sha256').update(text, 'utf8').digest('hex');
39	}
40	
41	export interface ManagedReviewExpectedBinding {
42	  providerHost: 'codex' | 'claude' | 'agy';
43	  headHash: string;
44	  materialHash: string;
45	  storyFilesHash: string;
46	  promptHash: string;
47	  envelopeId: string | null;
48	  managedPromptDigest: string;
49	}
50	
51	export type ReviewerExecutionAuthorityClassification =
52	  | 'managed-cross-provider-receipt'
53	  | 'native-host-signed-review'
54	  | 'degraded-single-host-local-only'
55	  | 'cross-provider-advisory-only';
56	
57	export interface ReviewerExecutionAuthority {
58	  classification: ReviewerExecutionAuthorityClassification;
59	  directSignedReviewAllowed: boolean;
60	  managedReceiptRequired: boolean;
61	  reviewGatePath: 'managed-receipt' | 'direct-signed-review' | 'local-host-verdict-only' | 'none';
62	}
63	
64	/**
65	 * Keep native-host, managed cross-provider, and explicit degraded assurance
66	 * semantically disjoint. A managed receipt is the only cross-provider CLI path
67	 * into REVIEW evidence; degraded single-host evidence remains a local DONE
68	 * assurance fact and never borrows either reviewer authority path.
69	 */
70	export function classifyReviewerExecutionAuthority(args: {
71	  executionMode: 'native-host' | 'cross-provider-cli';
72	  assuranceLevel: 'ordinary-review' | 'degraded-single-host';
73	  hasManagedEvidenceBinding: boolean;
74	}): ReviewerExecutionAuthority {
75	  if (args.assuranceLevel === 'degraded-single-host') {
76	    return {
77	      classification: 'degraded-single-host-local-only',
78	      directSignedReviewAllowed: false,
79	      managedReceiptRequired: false,
80	      reviewGatePath: 'local-host-verdict-only',
81	    };
82	  }
83	  if (args.executionMode === 'cross-provider-cli') {
84	    return args.hasManagedEvidenceBinding
85	      ? {
86	        classification: 'managed-cross-provider-receipt',
87	        directSignedReviewAllowed: false,
88	        managedReceiptRequired: true,
89	        reviewGatePath: 'managed-receipt',
90	      }
91	      : {
92	        classification: 'cross-provider-advisory-only',
93	        directSignedReviewAllowed: false,
94	        managedReceiptRequired: true,
95	        reviewGatePath: 'none',
96	      };
97	  }
98	  if (args.hasManagedEvidenceBinding) {
99	    return {
100	      classification: 'cross-provider-advisory-only',
101	      directSignedReviewAllowed: false,
102	      managedReceiptRequired: true,
103	      reviewGatePath: 'none',
104	    };
105	  }
106	  return {
107	    classification: 'native-host-signed-review',
108	    directSignedReviewAllowed: true,
109	    managedReceiptRequired: false,
110	    reviewGatePath: 'direct-signed-review',
111	  };
112	}
113	
114	export function resolveManagedReviewerBasePrompt(root: string, run: ReviewRun): string {
115	  if (run.assembledPrompt) return run.assembledPrompt;
116	  const body = resolvePromptRoleBody(run.lane, loadConfig(root).promptEnvelope).body;
117	  if (rawSha256(body) !== run.promptHash) {
118	    throw new Error('managed reviewer: legacy ReviewRun prompt hash does not match the canonical role body');
119	  }
120	  return body;
121	}
122	
123	export function buildManagedReviewerPrompt(root: string, run: ReviewRun): string {
124	  const binding = JSON.stringify({
125	    storyId: run.storyId,
126	    providerAgent: run.lane,
127	    lane: run.lane,
128	    reviewRunId: run.reviewRunId,
129	  });
130	  return [
131	    '--- BEGIN MANAGED REVIEW EVIDENCE PROTOCOL ---',
132	    `This provider run is already bound to ${binding}.`,
133	    'Do not call review_run_start, review_pass_set, or finding_add in this run.',
134	    'Your final assistant result MUST contain exactly one JSON object and no prose, tool call, or markdown fence. Do not call managed_review_proposal_set; tool-shell output is not formal evidence.',
135	    'Use schemaVersion="lattice.managed_review_final_proposal.v1" and the exact bound fields above. For a pass add conclusion="pass", note, and truthful readManifest/readLog. For findings add conclusion="findings", exact findings, and truthful read evidence.',
136	    'The managed host adapter reads only this bounded final assistant result after provider exit, seals the exact verdict, and then permits receipt import. The controller cannot substitute or override it.',
137	    '--- END MANAGED REVIEW EVIDENCE PROTOCOL ---',
138	    '',
139	    resolveManagedReviewerBasePrompt(root, run),
140	  ].join('\n');
141	}
142	
143	export function managedReviewerPromptDigest(root: string, run: ReviewRun): string {
144	  return sha256(buildManagedReviewerPrompt(root, run));
145	}
146	
147	function failedDiagnostic(): ProofAdmissibilityDiagnostic {
148	  return buildProofAdmissibilityDiagnostic({
149	    artifactKind: 'managed-review-evidence',
150	    consumer: 'REVIEW',
151	    claim: 'review-pass',
152	    mode: 'enforce',
153	    enforcedConsumers: ['REVIEW'],
154	    checks: {
155	      schemaVersion: 'lattice.managed_review_evidence_binding.v1',
156	      strictShapeValid: false,
157	      semanticDigestValid: false,
158	      signatureOrReceiptBindingValid: false,
159	      temporalAndMaterialBindingValid: false,
160	      subjectMatches: false,
161	      storyMatches: false,
162	      gatePhaseMatches: true,
163	      producerBoundaryTrusted: false,
164	    },
165	  });
166	}
167	
168	export function verifyManagedReviewEvidence(args: {
169	  root: string;
170	  storyId: string;
171	  agent: string;
172	  reviewRunId: string;
173	  lane: string;
174	  binding: ManagedReviewEvidenceBinding;
175	  expected: ManagedReviewExpectedBinding;
176	  evidence?: { kind: 'pass'; pass: ReviewPass } | { kind: 'finding'; finding: Finding };
177	}): ManagedReviewEvidenceVerification {
178	  let receipt: ManagedHostRunReceipt;
179	  let proposal: ManagedReviewEvidenceProposal | null;
180	  let runBinding: ReturnType<typeof readManagedHostRunBinding>;
181	  try {
182	    receipt = managedHostRunReceipt(args.root, args.binding.runId);
183	    proposal = readManagedReviewEvidenceProposal(args.root, args.binding.runId);
184	    runBinding = readManagedHostRunBinding(args.root, args.binding.runId);
185	  } catch (error) {
186	    const diagnostic = failedDiagnostic();
187	    return { valid: false, reason: diagnostic.reasons.join(','), diagnostic, receipt: null, proposal: null };
188	  }
189	  const terminalPath = join(managedHostRunDirectory(args.root, args.binding.runId), 'terminal.json');
190	  const runDirectory = managedHostRunDirectory(args.root, args.binding.runId);
191	  const observedTerminalDigest = sha256(readFileSync(terminalPath, 'utf8'));
192	  const observedProposalDigest = proposal
193	    ? sha256(readFileSync(join(runDirectory, 'evidence-proposal.json'), 'utf8'))
194	    : null;
195	  const proposalArtifacts = readdirSync(runDirectory)
196	    .filter(name => /^evidence-proposal(?:[.-].*)?\.json$/.test(name));
197	  const observedSpecDigest = sha256(readFileSync(join(runDirectory, 'spec.json'), 'utf8'));
198	  const observedEventJournalDigest = existsSync(join(runDirectory, 'events.jsonl'))
199	    ? sha256(readFileSync(join(runDirectory, 'events.jsonl'), 'utf8'))
200	    : sha256('');
201	  const observedResultDigest = existsSync(join(runDirectory, 'result.json'))
202	    ? sha256(readFileSync(join(runDirectory, 'result.json'), 'utf8'))
203	    : null;
204	  const shapeValid = args.binding.schemaVersion === 'lattice.managed_review_evidence_binding.v1'
205	    && proposal?.schemaVersion === 'lattice.managed_review_evidence_proposal.v1'
206	    && (proposal?.conclusion !== 'findings'
207	      || (Array.isArray(proposal.findings)
208	        && proposal.findings.length > 0
209	        && proposal.findings.every(isStrictManagedReviewFindingProposal)))
210	    && Number.isFinite(Date.parse(args.binding.importedAt))
211	    && args.binding.providerHost === args.expected.providerHost
212	    && args.binding.managedPromptDigest === args.expected.managedPromptDigest;
213	  const exactEvidenceMatches = (() => {
214	    if (!args.evidence) return true;
215	    if (!proposal) return false;
216	    if (args.evidence.kind === 'pass') {
217	      if (proposal.conclusion !== 'pass' || args.binding.proposalFindingIndex !== undefined) return false;
218	      return digestCanonicalJson({
219	        note: args.evidence.pass.note,
220	        readManifest: args.evidence.pass.readManifest,
221	        readLog: args.evidence.pass.readLog,
222	        readDiagnostics: args.evidence.pass.readDiagnostics,
223	      }) === digestCanonicalJson({
224	        note: proposal.note,
225	        readManifest: proposal.readManifest,
226	        readLog: proposal.readLog,
227	        readDiagnostics: proposal.readDiagnostics,
228	      });
229	    }
230	    if (proposal.conclusion !== 'findings') return false;
231	    const index = args.binding.proposalFindingIndex;
232	    if (!Number.isInteger(index) || index! < 0) return false;
233	    const candidate = proposal.findings?.[index!];
234	    if (!candidate) return false;
235	    return digestCanonicalJson({
236	      desc: args.evidence.finding.desc,
237	      severity: args.evidence.finding.severity,
238	      category: args.evidence.finding.category,
239	      evidenceState: args.evidence.finding.evidenceState ?? 'verified',
240	      uncertaintyReason: args.evidence.finding.uncertaintyReason,
241	      files: args.evidence.finding.files ?? [],
242	      status: args.evidence.finding.status,
243	      readManifest: args.evidence.finding.readManifest,
244	      readLog: args.evidence.finding.readLog,
245	      readDiagnostics: args.evidence.finding.readDiagnostics,
246	    }) === digestCanonicalJson({
247	      desc: candidate.desc,
248	      severity: candidate.severity,
249	      category: candidate.category,
250	      evidenceState: candidate.evidenceState ?? 'verified',
251	      uncertaintyReason: candidate.uncertaintyReason,
252	      files: candidate.files ?? [],
253	      status: 'open',
254	      readManifest: proposal.readManifest,
255	      readLog: proposal.readLog,
256	      readDiagnostics: proposal.readDiagnostics,
257	    });
258	  })();
259	  const externalImportSealMatches = (() => {
260	    if (!args.evidence) return true;
261	    const bindingPath = join(runDirectory, 'evidence-binding.json');
262	    const sealPath = join(runDirectory, 'evidence-binding.seal.json');
263	    if (!existsSync(bindingPath) || !existsSync(sealPath)) return false;
264	    try {
265	      const external = JSON.parse(readFileSync(bindingPath, 'utf8')) as Record<string, unknown>;
266	      const evidenceId = args.evidence.kind === 'pass' ? args.evidence.pass.id : args.evidence.finding.id;
267	      return external.schemaVersion === 'lattice.managed_review_evidence_import.v1'
268	        && external.runId === args.binding.runId
269	        && external.receiptId === args.binding.receiptId
270	        && external.storyId === args.storyId
271	        && external.reviewRunId === args.reviewRunId
272	        && external.lane === args.lane
273	        && external.importedAt === args.binding.importedAt
274	        && Array.isArray(external.importedIds)
275	        && external.importedIds.includes(evidenceId);
276	    } catch {
277	      return false;
278	    }
279	  })();
