249	export function classifyProviderRegistryLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
250	  const holder = snapshot.holder;
251	  if (!holder || holder.hostname !== hostname()) return 'unknown';
252	  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
253	  try {
254	    process.kill(holder.pid, 0);
255	  } catch (error) {
256	    const code = (error as NodeJS.ErrnoException).code;
257	    if (code === 'ESRCH') return 'stale';
258	    if (code !== 'EPERM') return 'unknown';
259	  }
260	  if (
261	    holder.pid === process.pid
262	    && !sameProcessStart(holder.processStartTimeMs, currentProcessStartTimeMs())
263	  ) return 'stale';
264	  return 'active';
265	}
