267	function withProviderRegistryLock<T>(
268	  dir: string,
269	  fn: () => T,
270	  timing: ProviderRegistryLockTiming = {},
271	): T {
272	  const lock = acquireMkdirLock(`${dir}.lock`, {
273	    label: 'provider-process-registry',
