281	      hostname: hostname(),
282	      command: 'provider-process-registry mutation',
283	      acquiredAt: new Date().toISOString(),
284	      lockId: randomUUID(),
285	      processStartTimeMs: currentProcessStartTimeMs(),
286	    },
287	  });
288	  try {
289	    return fn();
290	  } finally {
291	    lock.release();
292	  }
