304	export function acquireProviderProcessSlot(
305	  dir: string,
306	  cap: number,
307	  staleMs: number,
308	  now: number,
309	  meta: ProviderProcessSlotMeta,
310	  lockTiming: ProviderRegistryLockTiming = {},
311	): AcquiredProviderProcessSlot | null {
312	  mkdirSync(dir, { recursive: true });
