317	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
318	    if (live.length >= boundedCap) return null;
319	    const token = randomUUID();
320	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
321	    for (let index = 0; index < boundedCap; index += 1) {
