    && verifyManagedReviewProposalInvocationAttestation(paths, {
      storyId: args.proposal.storyId,
      providerAgent: args.proposal.providerAgent,
      lane: args.proposal.lane,
      reviewRunId: args.proposal.reviewRunId,
